const $=id=>document.getElementById(id),canvas=$('canvas'),ctx=canvas.getContext('2d');let photo=null,base=1,scale=1,x=0,y=0,drag=null,url=null;
let worker=null,checkTimer=null,revision=0,inFlight=false,checkTimeout=null,workerGeneration=0;
function draw(check=true){if(!photo)return;ctx.fillStyle='#fff';ctx.fillRect(0,0,630,810);const w=photo.width*base*scale,h=photo.height*base*scale;x=Math.min(Math.max(x,(630-w)/2),(w-630)/2);y=Math.min(Math.max(y,(810-h)/2),(h-810)/2);ctx.imageSmoothingEnabled=true;ctx.imageSmoothingQuality='high';ctx.drawImage(photo,(630-w)/2+x,(810-h)/2+y,w,h);if(check)scheduleChecks()}
function reset(){scale=1;x=y=0;$('zoom').value=1;draw()}
async function load(file){if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){$('status').textContent='Please choose a JPG, PNG, or WebP image.';return}if(file.size>40*1024*1024){$('status').textContent='Please choose a photo smaller than 40 MB.';return}try{const next=URL.createObjectURL(file);const img=new Image();await new Promise((ok,fail)=>{img.onload=ok;img.onerror=fail;img.src=next});if(url)URL.revokeObjectURL(url);url=next;photo=img;base=Math.max(630/img.width,810/img.height);$('empty').hidden=true;$('crop').hidden=false;$('zoom').disabled=false;$('reset').disabled=false;$('download').disabled=false;reset();$('status').textContent=img.width<630||img.height<810?'This image is smaller than the output. A higher-resolution original will give better detail.':'Drag to position your head, then use zoom to match the guides.'}catch{$('status').textContent='This photo could not be opened. Please try another image.'}}
$('upload').onclick=$('replace').onclick=()=>$('file').click();$('file').onchange=e=>{load(e.target.files[0]);e.target.value=''};$('zoom').oninput=e=>{scale=+e.target.value;draw()};$('reset').onclick=reset;$('showguides').onchange=e=>$('guides').hidden=!e.target.checked;
$('crop').onpointerdown=e=>{drag={x:e.clientX,y:e.clientY,ox:x,oy:y};$('crop').setPointerCapture(e.pointerId)};$('crop').onpointermove=e=>{if(!drag)return;const ratio=630/canvas.getBoundingClientRect().width;x=drag.ox+(e.clientX-drag.x)*ratio;y=drag.oy+(e.clientY-drag.y)*ratio;draw()};$('crop').onpointerup=$('crop').onpointercancel=()=>drag=null;
for(const event of ['dragenter','dragover'])$('drop').addEventListener(event,e=>{e.preventDefault();$('drop').classList.add('dragging')});$('drop').ondragleave=()=>$('drop').classList.remove('dragging');$('drop').ondrop=e=>{e.preventDefault();$('drop').classList.remove('dragging');load(e.dataTransfer.files[0])};$('download').onclick=()=>{if(!photo)return;draw(false);const type=$('format').value;canvas.toBlob(blob=>{if(!blob){$('status').textContent='Export failed. Please try again.';return}const link=document.createElement('a'),u=URL.createObjectURL(blob);link.href=u;link.download='indian-passport-630x810.'+(type==='image/png'?'png':'jpg');link.click();setTimeout(()=>URL.revokeObjectURL(u),1000);$('status').textContent=`Downloaded 630 × 810 px · ${Math.round(blob.size/1024)} KB. Review your photo before submitting.`},type,.95)};

function markPending(message='Checking your latest crop…'){ $('checksummary').textContent=message;$('checksummary').classList.add('busy');document.querySelectorAll('.checkrow').forEach(row=>row.classList.add('busy'));$('download').textContent='Download photo · checks pending ↓';}
function scheduleChecks(){revision++;clearTimeout(checkTimer);markPending(worker?'Checking your latest crop…':'Preparing on-device checks… First use loads the photo models.');checkTimer=setTimeout(runChecks,450);}
function analysisError(message){$('checksummary').textContent=message;$('checksummary').classList.remove('busy');$('checkresults').replaceChildren();const row=document.createElement('p');row.className='checkplaceholder';row.textContent='Photo not verified. Automatic checks are unavailable; downloading still saves your crop at 630 × 810 pixels.';$('checkresults').append(row);$('retrychecks').hidden=false;$('download').textContent='Download without verification ↓';}
function ensureWorker(){if(worker)return;const generation=++workerGeneration;worker=new Worker('./check-worker.js');worker.onmessage=({data})=>{if(generation!==workerGeneration)return;clearTimeout(checkTimeout);inFlight=false;if(data.id!==revision){runChecks();return}if(data.error){worker.terminate();worker=null;analysisError(data.error);return}renderChecks(data.rows);};worker.onerror=()=>{if(generation!==workerGeneration)return;clearTimeout(checkTimeout);inFlight=false;worker.terminate();worker=null;analysisError('Automatic checks could not start in this browser. Try again, or use a browser with WebAssembly support.');};}
async function runChecks(){if(!photo||inFlight)return;ensureWorker();const id=revision,generation=workerGeneration;inFlight=true;try{const bitmap=await createImageBitmap(canvas);if(id!==revision||generation!==workerGeneration){bitmap.close();inFlight=false;runChecks();return}worker.postMessage({id,bitmap,sourceWidth:photo.width,sourceHeight:photo.height,upscaled:base*scale>1.005},[bitmap]);checkTimeout=setTimeout(()=>{if(generation!==workerGeneration)return;workerGeneration++;worker.terminate();worker=null;inFlight=false;analysisError('Analysis timed out. The first run downloads about 40 MB of models and runtime; retry when your connection is ready.');},120000);}catch{inFlight=false;analysisError('This browser could not prepare the photo for automatic checks. Try another browser.');}}
function renderChecks(rows){$('checksummary').classList.remove('busy');$('retrychecks').hidden=false;const warnings=rows.filter(r=>r.status==='warn').length,unknown=rows.filter(r=>r.status==='review').length,passed=rows.filter(r=>r.status==='pass').length;$('checksummary').textContent=`${passed} checks look good${warnings?` · ${warnings} need attention`:''}${unknown?` · ${unknown} could not be assessed`:''}. Automated estimates; acceptance is decided by the passport authority.`;$('checkresults').replaceChildren();for(const result of rows){const row=document.createElement('article');row.className='checkrow '+result.status;const head=document.createElement('div');head.className='checkrow-head';const title=document.createElement('h3');title.textContent=result.title;const badge=document.createElement('span');badge.className='checkbadge';badge.textContent={pass:'✓ Looks good',warn:'! Needs attention',review:'? Not verified'}[result.status];const detail=document.createElement('p');detail.textContent=result.detail;head.append(title,badge);row.append(head,detail);$('checkresults').append(row)}$('download').textContent=warnings?'Download with warnings ↓':unknown?'Download · some checks unverified ↓':'Download passport photo ↓';}
$('retrychecks').onclick=()=>{if(photo)scheduleChecks()};
